-- ============================================================
-- AZUR — seed home-service therapist profiles into settings
-- (photos included; generated file — no need to read the blobs)
-- Where to run: Supabase Dashboard → SQL Editor → New query
-- Paste this whole file and press RUN. It should say "Success".
-- Safe to run more than once: existing entries are left untouched.
-- After this, therapists are managed from Admin → Settings.
-- ============================================================

-- Nour: add if missing entirely
update public.settings
set data = jsonb_set(data, '{locations,home-t1}', '{"name": "Nour", "area": "Home service", "home": true, "spec": "Holistic Massage", "desc": "Gentle, intuitive and deeply calming — Nour blends holistic massage with breathing work to melt tension away in your own space.", "photo": "data:image/jpeg;base64,", "hours": {"0": {"start": "10:00", "end": "19:00"}, "1": {"start": "10:00", "end": "19:00"}, "2": {"start": "10:00", "end": "19:00"}, "3": {"start": "10:00", "end": "19:00"}, "4": {"start": "10:00", "end": "19:00"}, "5": {"start": "10:00", "end": "19:00"}, "6": {"start": "10:00", "end": "19:00"}}}'::jsonb)
where id = 1 and not (data->'locations' ? 'home-t1');

-- Nour: entry already there (hours kept) but no profile yet — add it
update public.settings
set data = jsonb_set(jsonb_set(jsonb_set(data,
  '{locations,home-t1,spec}', '"Holistic Massage"'::jsonb),
  '{locations,home-t1,desc}', '"Gentle, intuitive and deeply calming — Nour blends holistic massage with breathing work to melt tension away in your own space."'::jsonb),
  '{locations,home-t1,photo}', '"data:image/jpeg;base64,"'::jsonb)
where id = 1 and (data->'locations' ? 'home-t1')
  and not (data->'locations'->'home-t1' ? 'photo');

